```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Paint the sky
  brush.fill("#87CEEB");
  brush.beginShape();
  for (let i = 0; i < 100; i++) {
    let x = random(0, 400);
    let y = random(0, 400);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Paint the green hills
  brush.fill("#006400");
  brush.beginShape();
  for (let i = 0; i < 100; i++) {
    let x = random(0, 400);
    let y = random(0, 400);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Paint the sunset
  brush.fill("#FF4500");
  brush.beginShape();
  for (let i = 0; i < 100; i++) {
    let x = random(0, 400);
    let y = random(0, 400);
    brush.vertex(x, y);
  }
  brush.endShape(true);
}
```

