  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB"); // Sky blue
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 0); // Top left
  brush.vertex(400, 0); // Top right
  brush.vertex(400, 400); // Bottom right
  brush.vertex(0, 400); // Bottom left
  brush.endShape(true);

  // Green hills
  brush.fill("#4682b4"); // Green
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 100); // Top left hill
  brush.vertex(400, 100); // Top right hill
  brush.vertex(400, 200); // Bottom right hill
  brush.vertex(0, 200); // Bottom left hill
  brush.endShape(true);

  // Sunset
  brush.fill("#FF4500"); // Orange
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(0, 250); // Top left sunset
  brush.vertex(400, 250); // Top right sunset
  brush.vertex(400, 350); // Bottom right sunset
  brush.vertex(0, 350); // Bottom left sunset
  brush.endShape(true);

  // Add some details
  brush.fill("#FFD700"); // Yellow
  brush.fillBleed(0.2);
  brush.beginShape();
  brush.vertex(0, 200); // Top left detail
  brush.vertex(400, 200); // Top right detail
  brush.vertex(400, 250); // Bottom right detail
  brush.vertex(0, 250); // Bottom left detail
  brush.endShape(true);
}
