  brush.beginShape();
  brush.vertex(200, 50); // Top of sun
  brush.vertex(250, 0); // Right of sun
  brush.vertex(300, 0); // Bottom of sun
  brush.vertex(250, 50); // Left of sun
  brush.endShape(true);

  // Clouds
  brush.fill("#E6E6E6"); // Light gray
  brush.fillBleed(0.1);
  brush.beginShape();
  brush.vertex(100, 100); // Top left cloud
  brush.vertex(150, 150); // Top right cloud
  brush.vertex(150, 200); // Bottom right cloud
  brush.vertex(100, 200); // Bottom left cloud
  brush.endShape(true);
}
